// All leads in the table (rows without a domain are ignored)
const leads = $('Get All Leads').all().map(item => item.json).filter(l => l.domain);

// One settings row per active tag
const settingsRows = $('Get Active Settings').all().map(item => item.json);

// A date written as year-month-day in Madrid time
function dayOf(value) {
  return new Date(value).toLocaleDateString('en-CA', { timeZone: 'Europe/Madrid' });
}
const today = dayOf(new Date());

// Statuses of leads that still wait for their email to be sent
const waitingStatuses = ['researched', 'written', 'awaiting approval', 'approved'];

const selected = [];

for (const settings of settingsRows) {
  const tag = settings.tag;
  const quota = Number(settings.dailyQuota) || 0;
  const includeMedium = settings.includeMedium === true;

  const tagLeads = leads.filter(l => l.tag === tag);

  // Emails already sent today
  const sentToday = tagLeads.filter(l => l.sentAt && dayOf(l.sentAt) === today).length;

  // Leads that wait: not written yet, waiting for your approval, or approved but not sent
  const waiting = tagLeads.filter(l => waitingStatuses.includes(l.status)).length;

  // How many more leads we need to research to fill the quota
  const needed = quota - sentToday - waiting;
  if (needed <= 0) continue;

  // Candidates: classified leads with a good rating
  const candidates = tagLeads.filter(l =>
    l.status === 'classified' &&
    (l.quality === 'High' || (includeMedium && l.quality === 'Medium'))
  );

  // High first, then the oldest lead first
  candidates.sort((a, b) => {
    if (a.quality !== b.quality) return a.quality === 'High' ? -1 : 1;
    return new Date(a.createdAt) - new Date(b.createdAt);
  });

  for (const lead of candidates.slice(0, needed)) {
    selected.push({ json: lead });
  }
}

return selected;

// TEST MODE: emails meant for companies go to MY_ADDRESS instead.
// Change TEST_MODE to false only after the end-to-end test is good.
const TEST_MODE = true;

// Your own address: it receives the approval previews, and every email in test mode
const MY_ADDRESS = 'your.address@example.com';

const leads = $('Get Leads To Send').all().map(item => item.json);
const settingsRows = $('Get Settings For Sending').all().map(item => item.json);

const results = [];

for (const lead of leads) {
  // Stop if the setup is broken, so nothing gets sent
  const settings = settingsRows.find(s => s.tag === lead.tag);
  if (!settings) throw new Error('No settings row for tag ' + lead.tag);

  // What to do with this lead:
  // "send"    = approved by you, or written on a tag that sends automatically
  // "preview" = written on a tag that needs your approval first
  const isApproved = lead.status === 'approved';
  const isAutomatic = settings.automaticEmail === true;
  const action = (isApproved || isAutomatic) ? 'send' : 'preview';

  const isSpanish = lead.language === 'Spanish';

  // The CV in the language of the email
  const cvUrl = String((isSpanish ? settings.cvUrlSpanish : settings.cvUrlEnglish) || '').trim();
  if (!cvUrl) throw new Error('No CV link for tag ' + lead.tag + ' in ' + lead.language);

  // Never continue without a subject, a body and a verified address
  if (!lead.emailSubject || !lead.emailBody) throw new Error('No email text for ' + lead.companyName);
  if (!lead.emailVerified || !lead.contactEmail) throw new Error('No verified address for ' + lead.companyName);

  // The explanation block is optional: some tags have one, others do not
  const explanation = String(
    (isSpanish ? settings.explanationSpanish : settings.explanationEnglish) || ''
  ).trim();

  // Fixed closing lines, always the same, in the language of the email
  const cvLine = isSpanish ? 'Adjunto mi CV.' : 'My CV is attached.';
  const signOff = isSpanish ? 'Un saludo,\nMiguel Hervás' : 'Best regards,\nMiguel Hervás';

  // The full email as the company will see it:
  // the written body, the explanation if there is one, then the CV line and the sign-off
  const parts = [String(lead.emailBody).trim()];
  if (explanation !== '') parts.push(explanation);
  parts.push(cvLine);
  parts.push(signOff);
  const fullBody = parts.join('\n\n');

  let sendTo, subject, body;

  if (action === 'preview') {
    // The preview always goes to you, with instructions on top and the real email below
    sendTo = MY_ADDRESS;
    subject = 'APPROVAL NEEDED: ' + lead.companyName + ' (' + lead.contactEmail + ')';
    body =
      'Reply "yes" to send this email to ' + lead.contactEmail + ', or "no" to reject it.\n\n' +
      'Subject: ' + lead.emailSubject + '\n\n' +
      '----------\n\n' +
      fullBody;
  } else if (TEST_MODE) {
    // Test mode: the real email comes to you, and the subject shows where it would have gone
    sendTo = MY_ADDRESS;
    subject = 'TEST for ' + lead.contactEmail + ': ' + lead.emailSubject;
    body = fullBody;
  } else {
    // The real email to the company
    sendTo = lead.contactEmail;
    subject = lead.emailSubject;
    body = fullBody;
  }

  results.push({
    json: {
      domain: lead.domain,
      action: action,
      sendTo: sendTo,
      subject: subject,
      body: body,
      cvUrl: cvUrl,
      isTest: TEST_MODE
    }
  });
}

return results;
